# Installs the NAS-Management agent for the logged-in user. Windows PowerShell 5.1.
#
# Run from a NON-elevated PowerShell, once for each Windows user to manage,
# with the code generated by the page (valid 30 minutes, once). The page
# "Network drives" gives the full command, or a double-click installer.
#
# What it does:
#   - creates %LOCALAPPDATA%\NAS-Management with agent.ps1 downloaded from the server;
#   - generates an RSA key pair: the private key stays here, DPAPI-encrypted;
#   - registers with the server and saves the token, DPAPI-encrypted;
#   - adds the logon start to HKCU\...\Run (no privileges needed) and starts
#     the agent right away, with no window.
#
#   install-agent.ps1 -Server http://192.168.1.50:8790 -Code ABC123DEF0 [-Language en|it]
#   install-agent.ps1 -Uninstall

param(
    [string]$Server,
    [Alias('Codice')][string]$Code,
    [string]$Language,
    [Alias('Cartella')][string]$Folder = (Join-Path $env:LOCALAPPDATA 'NAS-Management'),
    [Alias('SenzaAvvio')][switch]$NoStart,
    [Alias('Disinstalla')][switch]$Uninstall
)

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
$Folder = [IO.Path]::GetFullPath($Folder)
$defaultFolder = [IO.Path]::GetFullPath((Join-Path $env:LOCALAPPDATA 'NAS-Management'))
$runKey = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run'
$runName = 'NAS-Management agent'
$oldRunName = 'NAS-Management agente'
$agentPs1 = Join-Path $Folder 'agent.ps1'

if (-not $Language) { $Language = if ((Get-UICulture).Name -like 'it*') { 'it' } else { 'en' } }
$Language = if ($Language -like 'it*') { 'it' } else { 'en' }
$Texts = @{
    en = @{
        uninstalled = 'Agent uninstalled. The network drives stay where they are; remove the machine from the page too.'
        needArgs = 'Both -Server and -Code are needed: the page "Network drives" gives the full command.'
        elevated = 'Run the installation from a NON-elevated PowerShell: drives mounted by an elevated session do not show up in File Explorer.'
        rejected = 'Registration rejected: {0} {1}'
        registered = 'Registered as "{0}" on {1}.'
        started = 'Agent started and set to run at every logon. Log: {0}'
    }
    it = @{
        uninstalled = 'Agente disinstallato. Le unità di rete restano dove sono; la macchina va tolta anche dalla pagina.'
        needArgs = 'Servono -Server e -Code: il comando completo lo dà la pagina «Unità di rete».'
        elevated = 'Lancia l''installazione da una PowerShell NON elevata: le unità montate da una sessione elevata non compaiono in Esplora file.'
        rejected = 'Registrazione rifiutata: {0} {1}'
        registered = 'Registrato come «{0}» su {1}.'
        started = 'Agente avviato e impostato per partire a ogni accesso. Log: {0}'
    }
}
function T([string]$key) { $Texts[$Language][$key] }

# Only the agent of THIS folder (new or old file name): another
# installation, for example a test one in another folder, is left alone.
function StopAgent {
    $paths = @($agentPs1, (Join-Path $Folder 'agente.ps1')) | ForEach-Object { [IO.Path]::GetFullPath($_) }
    Get-CimInstance Win32_Process -Filter "Name = 'powershell.exe'" |
        Where-Object { $p = $_; $p.ProcessId -ne $PID -and $p.CommandLine -and ($paths | Where-Object { $p.CommandLine.IndexOf($_, [StringComparison]::OrdinalIgnoreCase) -ge 0 }) } |
        ForEach-Object {
            # first any children left hanging (net.exe waiting for an answer)
            Get-CimInstance Win32_Process -Filter "ParentProcessId = $($_.ProcessId)" | ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }
            Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue
        }
}

# The logon entries are removed only if they point to this folder.
function RemoveStart {
    foreach ($n in @($runName, $oldRunName)) {
        $value = (Get-ItemProperty -Path $runKey -Name $n -ErrorAction SilentlyContinue).$n
        if ($value -and $value.IndexOf($Folder, [StringComparison]::OrdinalIgnoreCase) -ge 0) {
            Remove-ItemProperty -Path $runKey -Name $n -ErrorAction SilentlyContinue
        }
    }
}

if ($Uninstall) {
    RemoveStart
    StopAgent
    if (Test-Path $Folder) { Remove-Item -Recurse -Force $Folder }
    T 'uninstalled'
    return
}

if (-not $Server -or -not $Code) { throw (T 'needArgs') }
$Server = $Server.TrimEnd('/')

$me = [Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()
if ($me.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) { throw (T 'elevated') }

Add-Type -AssemblyName System.Security
New-Item -ItemType Directory -Force -Path $Folder | Out-Null

function Protect([string]$name, [string]$text) {
    $b = [Security.Cryptography.ProtectedData]::Protect([Text.Encoding]::UTF8.GetBytes($text), $null, 'CurrentUser')
    $f = Join-Path $Folder $name
    [IO.File]::WriteAllBytes("$f.tmp", $b)
    Move-Item -Force "$f.tmp" $f
}

# 1. agent.ps1 from the server (bytes as they are, BOM included)
Invoke-WebRequest -UseBasicParsing -Uri "$Server/agent/agent.ps1" -OutFile "$agentPs1.tmp" -TimeoutSec 20
Move-Item -Force "$agentPs1.tmp" $agentPs1

# 2. keys and registration
$rsa = New-Object Security.Cryptography.RSACryptoServiceProvider 2048
$pub = $rsa.ExportParameters($false)
$body = ConvertTo-Json -Compress -InputObject ([ordered]@{
    code = $Code
    computer = $env:COMPUTERNAME
    user = "$env:USERDOMAIN\$env:USERNAME"
    public_key = [ordered]@{ n = [Convert]::ToBase64String($pub.Modulus); e = [Convert]::ToBase64String($pub.Exponent) }
})
try {
    $r = Invoke-RestMethod -Method Post -Uri "$Server/api/agent/register" -TimeoutSec 20 `
        -ContentType 'application/json; charset=utf-8' -Body ([Text.Encoding]::UTF8.GetBytes($body))
} catch {
    $detail = $_.ErrorDetails.Message
    try { $j = $detail | ConvertFrom-Json; if ($j.error) { $detail = $j.error } } catch { }
    throw ((T 'rejected') -f $_.Exception.Message, $detail)
}

Protect 'key.dpapi' $rsa.ToXmlString($true)
Protect 'token.dpapi' $r.token
$conf = Join-Path $Folder 'agent.json'
ConvertTo-Json -InputObject ([ordered]@{ server = $Server; id = $r.id; language = $Language }) | Set-Content -Path "$conf.tmp" -Encoding UTF8
Move-Item -Force "$conf.tmp" $conf
# Files of an earlier Italian installation in the same folder.
foreach ($f in @('agente.ps1', 'agente.json', 'chiave.dpapi', 'agente.ps1.precedente')) { Remove-Item -Force -Path (Join-Path $Folder $f) -ErrorAction SilentlyContinue }
(T 'registered') -f $r.id, $Server

# 3. start at logon and right away
if (-not $NoStart) {
    $command = "`"$env:WINDIR\System32\conhost.exe`" --headless powershell.exe -NoProfile -ExecutionPolicy Bypass -File `"$agentPs1`""
    $arguments = @('--headless', 'powershell.exe', '-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', "`"$agentPs1`"")
    if ($Folder -ne $defaultFolder) { $command += " -Folder `"$Folder`""; $arguments += @('-Folder', "`"$Folder`"") }
    RemoveStart
    Set-ItemProperty -Path $runKey -Name $runName -Value $command
    StopAgent
    Start-Process -FilePath "$env:WINDIR\System32\conhost.exe" -WindowStyle Hidden -ArgumentList $arguments
    (T 'started') -f (Join-Path $Folder 'agent.log')
}
